G=load()
def solve(I):
    H,W=len(I),len(I[0])
    vals=collections.Counter(x for row in I for x in row)
    bg=vals.most_common(1)[0][0]; mark=[k for k,v in vals.items() if k!=bg][0]
    seeds=[(r,c) for r in range(H) for c in range(W) if I[r][c]==mark]
    out=[row[:] for row in I]
    dirs=[(-1,-1),(-1,1),(1,-1),(1,1)]
    for sr,sc in seeds:
        for dr,dc in dirs:
            r,c=sr+dr,sc+dc
            while 0<=r<H and 0<=c<W and I[r][c]==bg:
                out[r][c]=mark; r+=dr; c+=dc
    return out
